INSERT INTO products (title, description, price, image_url, specifications, is_active, stock_quantity) VALUES
('Razer Viper V2 Pro Wireless Ultralight Gaming Mouse', 'Ultra-lightweight wireless gaming mouse at 58 grams with Focus Pro 30K optical sensor. Optical mouse switches rated for 90 million clicks. 90-hour battery life with hyperpolling wireless technology. 8 programmable buttons with on-board memory. Includes charging dock and Speedflex cable.', 129.99, 'https://images.unsplash.com/photo-1527814050087-3793815479db?auto=format&fit=crop&w=600&q=80', '{"brand":"Razer","category":"Peripherals"}', true, 10),
('Intel Core i7-14700K 20-Core 28-Thread Processor', 'Intel Core i7-14700K desktop processor with 20 cores (8P+12E) and 28 threads. Boost clock up to 5.6 GHz with 33MB Intel Smart Cache. 125W TDP with LGA 1700 socket. Supports DDR5-5600 and PCIe 5.0. Ideal for high-end gaming and productivity workloads.', 409.99, 'https://images.unsplash.com/photo-1591799264318-7e6ef8ddb7ea?auto=format&fit=crop&w=600&q=80', '{"brand":"Intel","category":"Processors"}', true, 10),
('Intel Core i7-14700K Desktop Processor 24 Cores (8P+16E) up to 5.6GHz', '"24-core (8 Performance-cores + 16 Efficient-cores) desktop processor with Intel Turbo Boost Max Technology 3.0 reaching up to 5.6 GHz clock speed. Features 33MB Intel Smart Cache, 20 PCIe 5.0 lanes, and integrated Intel UHD Graphics 770. Built on Intel 7 process technology with 125W TDP, supports DDR5-5600 and DDR4-3200 memory. Includes Intel Thermal Velocity Boost, Intel Adaptive Boost Technology, and Intel Deep Learning Boost for AI acceleration. Compatible with LGA 1700 socket motherboards with Intel 600/700 series chipsets. Perfect for high-end gaming, content creation, and professional workloads requiring maximum multi-threaded performance."', 399, 'https://images.unsplash.com/photo-1591799264318-7e6ef8ddb7ea?auto=format&fit=crop&w=600&q=80', '{"brand":"Intel","category":"Processors"}', true, 10),
('Intel Core i9-14900K 24-Core 32-Thread Desktop Processor', '"Intel Core i9-14900K desktop processor with 24 cores (8P+16E) and 32 threads. Boost clock up to 6.0 GHz with Thermal Velocity Boost. 36MB Intel Smart Cache with 125W base power, 253W max turbo. Supports DDR5-5600 and DDR4-3200 memory. LGA 1700 socket. Perfect for enthusiast gaming and workstation performance."', 589.99, 'https://images.unsplash.com/photo-1591799264318-7e6ef8ddb7ea?auto=format&fit=crop&w=600&q=80', '{"brand":"Intel","category":"Processors"}', true, 10),
('Keychron Q1 Pro QMK/VIA Wireless Mechanical Keyboard', '"QMK/VIA programmable mechanical keyboard with hot-swappable Gateron switches. Aluminum frame with double-shot PBT keycaps. Bluetooth 5.1 and wired USB-C connectivity. RGB backlighting with 22 RGB modes. Compatible with Mac, Windows, and Linux. Includes keycap puller and switch puller."', 199.99, 'https://images.unsplash.com/photo-1618384881928-02484c98f801?auto=format&fit=crop&w=600&q=80', '{"brand":"Keychron","category":"Peripherals"}', true, 10),
('WD Black SN850X 2TB NVMe PCIe Gen4 SSD', '"2TB NVMe SSD with 7,300 MB/s sequential read and 6,600 MB/s sequential write speeds. PCIe Gen4 x4 interface with M.2 2280 form factor. 1,200 TBW endurance with 5-year warranty. Western Digital Dashboard software for monitoring. Perfect for gaming and content creation."', 149.99, 'https://images.unsplash.com/photo-1587614382346-4ec70e388b28?auto=format&fit=crop&w=600&q=80', '{"brand":"Western Digital","category":"Storage"}', true, 10),
('Corsair Vengeance 32GB (2x16GB) DDR5 5600MHz CL40 Desktop Memory', '32GB (2x16GB) DDR5 DRAM memory kit running at 5600MHz with CL40-40-40-77 timings at 1.25V. Features custom-designed aluminum heat spreaders with black finish and precision-screened ICs for reliable performance. Optimized for Intel XMP 3.0 with one-click overclocking support and onboard PMIC with integrated voltage regulation. Ten-layer PCB design for superior signal integrity and stability. Compatible with Intel 600/700 series and AMD AM5 platforms. Includes lifetime warranty and Corsair iCUE software support for real-time monitoring and customization.', 115, 'https://images.unsplash.com/photo-1562976540-1502c2145186?auto=format&fit=crop&w=600&q=80', '{"brand":"Corsair","category":"Memory"}', true, 10),
('Sony WH-1000XM5 Wireless Industry Leading Noise Canceling Headphones', '"Industry-leading wireless noise canceling headphones featuring Integrated Processor V1 and HD Noise Cancelling Processor QN1e for superior noise cancellation. 30mm dome-type drivers with neodymium magnets deliver exceptional sound quality with 4Hz-40kHz frequency response. 30-hour battery life with 3-minute quick charge providing 3 hours of playback. Includes multipoint connection, speak-to-chat technology, and optimized noise canceling with atmospheric pressure optimizing for travel. Foldable design with carrying case, touch sensor controls, and wear detection. Supports LDAC, AAC, and SBC codecs with Bluetooth 5.2 connectivity. Perfect for travel, office, and daily commutes with premium comfort and audio performance."', 399, 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=600&q=80', '{"brand":"Sony","category":"Headphones"}', true, 10),
('ASUS ROG Swift Pro PG248QP 24.5-inch 360Hz Gaming Monitor', '24.5-inch esports gaming monitor with 360Hz refresh rate and 0.5ms response time. Fast IPS panel with G-SYNC compatibility. 1080p resolution with 100% sRGB coverage. Height adjustable stand with ergonomic tilt. DisplayWidget software for easy settings. Perfect for competitive gaming.', 599.99, 'https://images.unsplash.com/photo-1556155092-490a1ba16284?auto=format&fit=crop&w=600&q=80', '{"brand":"Asus","category":"Monitors"}', true, 10),
('ASUS ROG Maximus Z790 Hero WiFi 6E LGA 1700 ATX Gaming Motherboard', '"Premium E-ATX gaming motherboard with Intel Z790 chipset supporting 12th/13th/14th Gen Intel processors. Features 20+1 power stages rated at 105A each with dual 8-pin ProCool II power connectors and robust VRM cooling with integrated I/O cover and high-conductivity thermal pads. Includes 5x M.2 slots (3x PCIe 4.0, 2x PCIe 5.0) with M.2 heatsinks and backplates, PCIe 5.0 x16 SafeSlot with Q-Release, and Thunderbolt 4 header. Networking includes Intel 2.5Gb Ethernet, Intel WiFi 6E with 6GHz band support, and ASUS LANGuard protection. Audio features SupremeFX ALC4082 codec with ESS SABRE9218 DAC. Comprehensive cooling with multiple fan headers, water pump headers, and thermal sensors. RGB lighting with Aura Sync support and dual BIOS with BIOS FlashBack. Extensive rear I/O including USB 3.2 Gen 2x2 Type-C, HDMI 2.1, and DisplayPort 1.4."', 629.99, 'https://images.unsplash.com/photo-1512499617640-c74ae3a79d37?auto=format&fit=crop&w=600&q=80', '{"brand":"ASUS","category":"Motherboards"}', true, 10),
('G.Skill Trident Z5 Neo RGB 32GB DDR5 6000MHz CL30 AMD EXPO', 'G.Skill Trident Z5 Neo RGB 32GB (2x16GB) DDR5 6000MHz CL30 memory kit optimized for AMD AM5 platforms. Samsung B-die ICs with on-die ECC support. Intel XMP 3.0 certified with sleek aluminum heatspreader and RGB lighting. Ideal for Ryzen 7000 series processors.', 119.99, 'https://images.unsplash.com/photo-1591485423007-765bde4139ef?auto=format&fit=crop&w=600&q=80', '{"brand":"G.Skill","category":"Memory"}', true, 10),
('ASUS ROG Zephyrus G14 14-inch Gaming Laptop Ryzen 9 RTX 4060', '"14-inch gaming laptop with AMD Ryzen 9 7940HS processor and NVIDIA GeForce RTX 4060 laptop GPU. Features 14-inch Nebula HDR Display with 3ms response time, 100% DCI-P3 color gamut, and FreeSync Premium. 16GB LPDDR5 RAM and 1TB PCIe 4.0 SSD. Includes ROG Intelligent Cooling with vapor chamber and liquid metal on CPU. 76Wh battery with 240W power adapter. Weight: 3.64 lbs with magnesium-aluminum chassis."', 1449.99, 'https://images.unsplash.com/photo-1588872657578-7efd1f1555ed?auto=format&fit=crop&w=600&q=80', '{"brand":"ASUS","category":"Laptops"}', true, 10),
('Marshall Emberton II Portable Bluetooth Speaker with 30+ Hours Playtime', '"Portable Bluetooth speaker with 30+ hours of portable playtime on a single charge. Features dual 10W tweeters and a 20W subwoofer for powerful, clear sound. Bluetooth 5.1 with multipoint connection for seamless switching between devices. Stack mode allows multiple speakers to be connected for enhanced sound. IP67 dust and water resistance for outdoor use. Built-in rechargeable battery with USB-C charging. Classic Marshall design with iconic brass details and silicone exterior. Perfect for travel, outdoor activities, and home use with Marshall signature sound quality."', 169, 'https://images.unsplash.com/photo-1545454675-3531b543be5d?auto=format&fit=crop&w=600&q=80', '{"brand":"Marshall","category":"Speakers"}', true, 10),
('NVIDIA GeForce RTX 4070 12GB GDDR6X Graphics Card', '"High-performance graphics card with 12GB GDDR6X memory and 5888 CUDA cores. 2520 MHz boost clock with dual axial-tech fans and 0dB technology. Features 2x HDMI 2.1 and 3x DisplayPort 1.4a outputs. PCIe 4.0 interface with 192-bit memory bus. Includes NVIDIA DLSS 3, ray tracing cores, and NVIDIA Reflex technology. Perfect for 1440p gaming and content creation."', 599.99, 'https://images.unsplash.com/photo-1624701928517-44c8ac49d93c?auto=format&fit=crop&w=600&q=80', '{"brand":"NVIDIA","category":"Graphics Cards"}', true, 10),
('Wacom Intuos Medium Bluetooth Graphics Drawing Tablet', '"Drawing tablet with 8.7x5.8 inch active area and 8192 pressure levels. 4 customizable express keys and multi-touch support. Includes battery-free stylus with pen holder and extra nibs. Bluetooth connectivity for wireless use. Compatible with Windows, Mac, and Android. Perfect for digital art and design."', 299.99, 'https://images.unsplash.com/photo-1613040819383-29ae0ec5d127?auto=format&fit=crop&w=600&q=80', '{"brand":"Wacom","category":"Peripherals"}', true, 10),
('Sony A7 IV Full-Frame Mirrorless Camera 33MP 4K 60p', '"Full-frame mirrorless camera with 33MP Exmor R CMOS sensor and BIONZ XR processor. 4K 60p video with 10-bit 4:2:2 internal recording, S-Cinetone color profile, and active mode stabilization. 759 phase-detection AF points covering 94% of sensor area with real-time tracking for humans and animals. 5-axis in-body image stabilization with 5.5 stops compensation. 3.68M-dot OLED EVF and 3.0-inch vari-angle LCD touchscreen. Dual SD card slots with UHS-II support. USB-C streaming at 4K, full-size HDMI port, and headphone/mic jacks. Weather-sealed magnesium alloy body. Perfect for hybrid shooters needing exceptional photo and video capabilities."', 2499, 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?auto=format&fit=crop&w=600&q=80', '{"brand":"Sony","category":"Cameras"}', true, 10),
('"Samsung 980 Pro 1TB PCIe 4.0 NVMe M.2 SSD 7,000 MB/s"', '"NVMe PCIe 4.0 SSD with 7,000 MB/s sequential read and 5,000 MB/s sequential write speeds. 1TB capacity with 1GB LPDDR4 DRAM cache and Samsung''s proprietary controller. Intelligent TurboWrite 2.0 technology for sustained high performance. Thermal control with nickel-coated controller and heat spreader label. 600 TBW endurance with 5-year limited warranty. Samsung Magician software for drive management and performance optimization. Perfect for gaming, content creation, and professional applications requiring high-speed storage."', 109.99, 'https://images.unsplash.com/photo-1597872200370-499df51bbd70?auto=format&fit=crop&w=600&q=80', '{"brand":"Samsung","category":"Storage"}', true, 10),
('Sony ZV-E10 Content Creator Mirrorless Camera with 16-50mm Lens', '"APS-C mirrorless camera specifically designed for content creators with 24.2MP Exmor CMOS sensor and BIONZ X processor. Unlimited 4K video recording with full pixel readout, product showcase setting for automatic focus shift, and background defocus button. Includes directional 3-capsule microphone with windscreen and MI shoe for digital audio. Fully articulating LCD touchscreen, real-time eye AF for humans and animals, and real-time tracking. 425 phase-detection AF points covering 84% of sensor area. USB streaming at 4K with UVC/UAC support. Compact body with E-mount lens compatibility. Perfect for vlogging, YouTube, streaming, and content creation with professional video features."', 799.99, 'https://images.unsplash.com/photo-1502920917128-1aa500764cbd?auto=format&fit=crop&w=600&q=80', '{"brand":"Sony","category":"Cameras"}', true, 10),
('Herman Miller Aeron Gaming Chair Remastered - Size C Titanium', '"Legendary ergonomic gaming chair with 8Z Pellicle suspension material for weight distribution and airflow. Fully adjustable PostureFit SL lumbar support with 12-year warranty. Size C for taller users (6''2"" to 6''10"") with enhanced seat depth. Titanium finish with gaming-specific color accents. Features tilt limiter with forward tilt function, adjustable armrests (height, pivot, width, depth), and breathable mesh material. Self-adjusting tilt mechanism responds to user movement. Certified by orthopedic surgeons and tested for 24/7 commercial use. Perfect for extended gaming sessions with premium ergonomic support."', 1695, 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?auto=format&fit=crop&w=600&q=80', '{"brand":"Herman Miller","category":"Furniture"}', true, 10),
('MSI Ventus 2X RTX 4070 Super 12GB OC', '"MSI Gaming GeForce RTX 4070 Super 12GB Ventus 2X OC graphics card with dual Torx Fan 4.0 and zero-frozr technology. Features 7168 CUDA cores, 2565 MHz boost clock, and 12GB GDDR6X memory. Reinforced backplate with airflow vents and custom PCB design. Perfect for high-performance 1440p gaming and content creation."', 619.99, 'https://images.unsplash.com/photo-1624701928517-44c8ac49d93c?auto=format&fit=crop&w=600&q=80', '{"brand":"MSI","category":"Graphics Cards"}', true, 10),
('AMD Ryzen 9 7950X3D 16-Core 32-Thread Gaming Processor with 3D V-Cache', '"World''s fastest gaming processor with AMD 3D V-Cache technology featuring 144MB total cache (128MB L3 + 16MB L2). Zen 4 architecture with 16 cores/32 threads, boost clock up to 5.7GHz, and AMD EXPO memory overclocking. Built on 5nm process with integrated RDNA 2 graphics. Supports PCIe 5.0 and DDR5-5200. Asymmetrical cache design with 8 cores optimized for gaming and 8 cores for productivity. Includes AMD Ryzen Master utility and Wraith Prism RGB cooler. 120W TDP, compatible with AM5 socket motherboards. Perfect for enthusiasts needing ultimate gaming and productivity performance."', 699.99, 'https://images.unsplash.com/photo-1588872657578-7efd1f1555ed?auto=format&fit=crop&w=600&q=80', '{"brand":"AMD","category":"Processors"}', true, 10),
('LG C3 42-inch 4K OLED Smart TV 120Hz G-SYNC Compatible', '"42-inch OLED TV/monitor with 4K resolution and 120Hz refresh rate. Infinite contrast ratio with perfect blacks and 1.5 million:1 contrast. 100% color fidelity with 10-bit color depth. NVIDIA G-SYNC and AMD FreeSync Premium certified. 0.1ms response time for blur-free motion. Four HDMI 2.1 ports with 48Gbps bandwidth supporting 4K 120Hz with HDR. Dolby Vision IQ and Dolby Atmos support. webOS smart platform with gaming dashboard. Perfect for immersive gaming, home theater, and professional content creation."', 899.99, 'https://images.unsplash.com/photo-1593305841991-05c297ba4575?auto=format&fit=crop&w=600&q=80', '{"brand":"LG","category":"Monitors"}', true, 10),
('Google Pixel 8 Pro 128GB Obsidian Unlocked Smartphone', '"The most powerful Pixel with Google Tensor G3 chip and pro-level camera system. 50MP main camera with Super Res Zoom up to 30x, 48MP ultrawide, and 48MP telephoto. 6.7-inch QHD+ LTPO OLED display with 120Hz refresh rate. 5050mAh battery with fast wireless charging. Android 14 with 7 years of OS updates. Titan M2 security chip, IP68 water resistance, and 5G connectivity. Features Magic Editor, Best Take, and Audio Magic Eraser. Perfect for photography enthusiasts and Android power users."', 999, 'https://images.unsplash.com/photo-1696429104080-0435978f6974?auto=format&fit=crop&w=600&q=80', '{"brand":"Google","category":"Smartphones"}', true, 10),
('Alienware AW3423DWF 34-inch QD-OLED Curved Gaming Monitor 165Hz', '"34-inch QD-OLED curved gaming monitor with 3440x1440 resolution and 1800R curvature. Quantum Dot OLED technology delivers infinite contrast ratio and 99.3% DCI-P3 color gamut. 165Hz refresh rate (175Hz overclockable) with 0.1ms GtG response time. DisplayHDR True Black 400 certified with AMD FreeSync Premium Pro. Proprietary heatsink for thermal management and pixel refresh technology. Connectivity includes 2x HDMI 2.0, DisplayPort 1.4, 4x USB 3.2 Gen 1, and 3.5mm audio. Factory color calibrated with delta-E <2. 3-year warranty with burn-in protection. Perfect for immersive gaming and content creation."', 999.99, 'https://images.unsplash.com/photo-1556155092-490a1ba16284?auto=format&fit=crop&w=600&q=80', '{"brand":"Alienware","category":"Monitors"}', true, 10),
('AMD Radeon RX 7900 XTX 24GB GDDR6 Gaming Graphics Card', '"High-performance gaming GPU with AMD RDNA 3 architecture featuring chiplet design. 96 Compute Units delivering 61 TFLOPs peak performance. 24GB GDDR6 memory on 384-bit bus with 20 Gbps speed and 960 GB/s bandwidth. DisplayPort 2.1 support for 8K 165Hz or 4K 480Hz. 96MB Infinity Cache, dedicated AI accelerators, and 2nd-gen ray tracing. Advanced cooling with vapor chamber and triple-fan design. Supports FidelityFX Super Resolution 3, HYPR-RX, and AV1 encoding. Perfect for 4K gaming, content creation, and professional visualization."', 999.99, 'https://images.unsplash.com/photo-1624701928517-44c8ac49d93c?auto=format&fit=crop&w=600&q=80', '{"brand":"AMD","category":"Graphics Cards"}', true, 10),
('LG 27UN850-W 27-inch 4K UHD IPS Monitor with USB-C', '"27-inch 4K UHD IPS monitor with 3840x2160 resolution and 60Hz refresh rate. 95% DCI-P3 color gamut with HDR10 support. USB-C connectivity with 60W power delivery for laptop charging. Ergonomic stand with height, tilt, and pivot adjustment. Built-in KVM switch for multi-device control. Perfect for productivity and professional work."', 449.99, 'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=600&q=80', '{"brand":"LG","category":"Monitors"}', true, 10),
('Gigabyte Z790 Aorus Master X WiFi 7 Intel Motherboard', '"Gigabyte Z790 Aorus Master X Intel motherboard with 20+1+2 phases VRM. Features PCIe 5.0 M.2 with thermal guard, WiFi 7, and 10GbE LAN. EZ-Latch Plus for tool-less installation and RGB FUSION 2.0. Perfect for 14th Gen Intel processors requiring maximum performance."', 499.99, 'https://images.unsplash.com/photo-1512499617640-c74ae3a79d37?auto=format&fit=crop&w=600&q=80', '{"brand":"Gigabyte","category":"Motherboards"}', true, 10),
('Dell XPS 15 9530 15.6-inch OLED Laptop i9 RTX 4070 32GB 1TB', 'High-performance 15.6-inch laptop with Intel Core i9-13900H processor and NVIDIA RTX 4070 graphics. InfinityEdge display with 3.5K OLED resolution and 100% DCI-P3. 32GB DDR5 RAM and 1TB PCIe SSD. Precision touchpad with haptic feedback and 4-speaker soundbar. 86Wh battery with ExpressCharge. CNC-machined aluminum chassis in platinum silver. Perfect for creative professionals and power users.', 1899, 'https://images.unsplash.com/photo-1593642632823-8f785ba67e45?auto=format&fit=crop&w=600&q=80', '{"brand":"Dell","category":"Laptops"}', true, 10),
('Corsair 3500X ARGB Tempered Glass Mid-Tower Case', 'Corsair 3500X ARGB mid-tower case with tempered glass front and side panels. Includes three RS120 ARGB fans with iCUE lighting controller. Supports up to 360mm radiators and 10 fan positions. Tool-less drive installation with USB-C front panel. Perfect for high-airflow builds.', 109.99, 'https://images.unsplash.com/photo-1587202372775-e229f172b9d7?auto=format&fit=crop&w=600&q=80', '{"brand":"Corsair","category":"Cases"}', true, 10),
('MSI MPG 271QRX QD-OLED 27-inch 360Hz Gaming Monitor', '"MSI MPG 271QRX QD-OLED 27-inch 360Hz gaming monitor with 2560x1440 resolution. QD-OLED panel with 0.03ms response time and true black display. Features HDMI 2.1, DisplayPort 1.4a, and USB-C with 98% DCI-P3 coverage. Includes OLED Care 2.0 for burn-in protection and gaming intelligence features. Perfect for competitive gaming."', 899.99, 'https://images.unsplash.com/photo-1556155092-490a1ba16284?auto=format&fit=crop&w=600&q=80', '{"brand":"MSI","category":"Monitors"}', true, 10),
('Elgato Stream Deck MK.2 15-Key Studio Controller for Streaming', '"Professional studio controller with 15 customizable LCD keys displaying icons or text. Improved non-slip stand with adjustable tilt and detachable USB-C cable. Integration with 200+ apps including OBS, Twitch, YouTube, and Discord. Create multi-actions with multiple steps, timers, and conditional logic. Stream Deck software with plugin marketplace, folder navigation, and profile switching. Perfect for streamers and content creators for scene control, audio adjustment, and workflow automation. Compatible with Windows 10/11 and macOS 11+."', 149.99, 'https://images.unsplash.com/photo-1593305841991-05c297ba4575?auto=format&fit=crop&w=600&q=80', '{"brand":"Elgato","category":"Streaming"}', true, 10),
('Seasonic FOCUS Plus Gold 850W ATX 3.0 Modular Power Supply', '850W ATX 3.0 power supply with 80 PLUS Gold efficiency. Fully modular with native 12VHPWR connector for next-gen GPUs. 135mm fluid dynamic bearing fan with hybrid silent fan control. 100% Japanese capacitors at 105°C. 10-year warranty. Perfect for high-end gaming PCs requiring stable power delivery.', 149.99, 'https://images.unsplash.com/photo-1600003263720-95b45a4035d5?auto=format&fit=crop&w=600&q=80', '{"brand":"Seasonic","category":"Power Supplies"}', true, 10),
('Gigabyte AORUS RTX 4070 Ti Super 16GB Master', '"Gigabyte AORUS GeForce RTX 4070 Ti Super 16GB graphics card with WINDFORCE cooling system. Features 3x 100mm unique blade fans, alternate spinning, and 10 composite copper heat pipes. Includes RGB lighting with digital display, dual UEFI BIOS, and metal backplate. Delivers exceptional 1440p gaming performance with ray tracing and DLSS 3.5."', 879.99, 'https://images.unsplash.com/photo-1624701928517-44c8ac49d93c?auto=format&fit=crop&w=600&q=80', '{"brand":"Gigabyte","category":"Graphics Cards"}', true, 10),
('Lenovo Legion Pro 7i 16-inch i9 RTX 4080 Gaming Laptop', '16-inch Legion gaming laptop with Intel i9-14900HX and RTX 4080. 2560x1600 display with 240Hz refresh rate and 500 nits brightness. 32GB DDR5 RAM and 2TB PCIe SSD. Legion Coldfront cooling system with vapor chamber. Per-key RGB keyboard with 1.5mm travel. Perfect for competitive gaming.', 2799.99, 'https://images.unsplash.com/photo-1525547719571-a2d4ac8945e2?auto=format&fit=crop&w=600&q=80', '{"brand":"Lenovo","category":"Laptops"}', true, 10),
('Garmin Fenix 7X Pro Solar Multisport GPS Watch with Flashlight', '"Multisport GPS watch with solar charging and built-in LED flashlight. 1.4-inch sunlight-readable display with sapphire crystal. Power Sapphire solar lens for extended battery life. Multi-band GPS, heart rate monitoring, and Pulse Ox. Built-in LED flashlight with strobe and red safety light. Advanced training metrics, maps, and music storage. 51mm fiber-reinforced polymer case with titanium bezel. Perfect for outdoor adventures and serious athletes."', 899, 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=600&q=80', '{"brand":"Garmin","category":"Wearables"}', true, 10),
('WD Black SN770 1TB PCIe Gen4 NVMe Gaming SSD', '"Western Digital Black SN770 1TB NVMe SSD with PCIe Gen4 interface. 5,150 MB/s sequential read and 4,900 MB/s write speeds. Western Digital nCache 4.0 technology with low power consumption. 600 TBW endurance with 5-year warranty. Ideal for gaming and everyday computing."', 79.99, 'https://images.unsplash.com/photo-1587614382346-4ec70e388b28?auto=format&fit=crop&w=600&q=80', '{"brand":"WD","category":"Storage"}', true, 10),
('Samsung Galaxy Tab S9 Ultra 14.6-inch 256GB WiFi', '14.6-inch AMOLED tablet with 120Hz refresh rate and Snapdragon 8 Gen 2 processor. 12GB RAM and 256GB storage with microSD expansion. S Pen included with Bluetooth and air actions. Quad speakers with AKG tuning. 11200mAh battery with 45W fast charging. Perfect for productivity and entertainment.', 1199.99, 'https://images.unsplash.com/photo-1546054454-aa26e2b734c7?auto=format&fit=crop&w=600&q=80', '{"brand":"Samsung","category":"Tablets"}', true, 10),
('Apple MacBook Pro 14-inch M3 Pro 12-core 18GB RAM 1TB SSD', '"Professional laptop with Apple M3 Pro chip featuring 12-core CPU and 18-core GPU. 14.2-inch Liquid Retina XDR display with 1600 nits peak brightness. 18GB unified memory and 1TB SSD. Three Thunderbolt 4 ports, HDMI, SDXC slot. 1080p FaceTime HD camera and six-speaker sound system. 18-hour battery life with 70W USB-C adapter. MacOS Sonoma with iPhone integration. Perfect for professionals and creatives."', 1599, 'https://images.unsplash.com/photo-1517336714460-d150857dc822?auto=format&fit=crop&w=600&q=80', '{"brand":"Apple","category":"Laptops"}', true, 10),
('Fractal Design North Walnut ATX Mid Tower Case', 'North ATX mid-tower case with walnut front panel and mesh side panel. Supports up to E-ATX motherboards and 360mm radiators. Includes three 140mm fans with PWM control. Tool-less drive installation and velcro cable management. Tempered glass side panel. Perfect for premium PC builds with natural aesthetics.', 139.99, 'https://images.unsplash.com/photo-1587202372775-e229f172b9d7?auto=format&fit=crop&w=600&q=80', '{"brand":"Fractal Design","category":"Cases"}', true, 10),
('Audio-Technica ATH-M50x Professional Studio Monitor Headphones', '"Professional studio monitor headphones with 45mm large-aperture drivers. 15-28,000 Hz frequency response and 38 ohm impedance. Circumaural design with professional-grade earpads and headband. Includes detachable cables and protective carrying case. Perfect for studio monitoring and critical listening."', 149.99, 'https://images.unsplash.com/photo-1484704849700-f032a568e944?auto=format&fit=crop&w=600&q=80', '{"brand":"Audio-Technica","category":"Headphones"}', true, 10),
('ASUS RT-AX88U Pro Dual-Band WiFi 6 Router 6 Gbps', '"Dual-band WiFi 6 router with 6 Gbps total speed and 160MHz channels. 2.0GHz quad-core processor with 1GB RAM. Dual 2.5G ports for WAN/LAN aggregation and four Gigabit LAN ports. AiProtection Pro with lifetime security, adaptive QoS, and VPN Fusion. AiMesh support for mesh networking. 8 external antennas with RangeBoost Plus. USB 3.2 Gen 1 port for media sharing. Perfect for high-performance home networks and gaming."', 299.99, 'https://images.unsplash.com/photo-1544197150-b99a580bb7a8?auto=format&fit=crop&w=600&q=80', '{"brand":"ASUS","category":"Networking"}', true, 10),
('ViewSonic Elite XG321UG 32-inch 4K 144Hz Mini-LED Monitor', '"ViewSonic Elite XG321UG 32-inch 4K 144Hz Mini-LED gaming monitor with 1152 local dimming zones. Features 1ms response time, DisplayHDR 1000, and 98% DCI-P3 coverage. Includes NVIDIA G-SYNC Ultimate, RGB lighting, and mouse bungee. Built-in headphone stand and USB 3.2 hub. Perfect for competitive and immersive gaming."', 1499.99, 'https://images.unsplash.com/photo-1556155092-490a1ba16284?auto=format&fit=crop&w=600&q=80', '{"brand":"ViewSonic","category":"Monitors"}', true, 10),
('Cooler Master MasterLiquid 360 Atmos AIO with LCD Display', 'Cooler Master MasterLiquid 360 Atmos AIO liquid cooler with dual chamber pump. Three SickleFlow Edge 120mm ARGB fans with daisy-chain design. 2.1-inch IPS LCD display with real-time system monitoring. Compatible with Intel LGA1700/1200 and AMD AM5/AM4.', 199.99, 'https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=600&q=80', '{"brand":"Cooler Master","category":"Cooling"}', true, 10),
('Sonos Five Premium Smart Speaker with Trueplay', 'Premium smart speaker with Trueplay tuning technology. Three tweeters and three mid-woofers for room-filling sound. AirPlay 2 and Spotify Connect support. Voice control with Sonos Voice and Amazon Alexa. WiFi and Ethernet connectivity. Perfect for multi-room audio systems.', 549.99, 'https://images.unsplash.com/photo-1545454675-3531b543be5d?auto=format&fit=crop&w=600&q=80', '{"brand":"Sonos","category":"Speakers"}', true, 10),
('Acer Predator X27U 27-inch OLED 240Hz Gaming Monitor', '"Acer Predator X27U 27-inch OLED 240Hz gaming monitor with 2560x1440 resolution. OLED panel with 0.01ms response time and 1,000,000:1 contrast ratio. Features NVIDIA G-SYNC compatibility, HDR10, and 99% DCI-P3 color gamut. Includes RGB lighting, height-adjustable stand, and USB hub. Perfect for immersive gaming."', 749.99, 'https://images.unsplash.com/photo-1556155092-490a1ba16284?auto=format&fit=crop&w=600&q=80', '{"brand":"Acer","category":"Monitors"}', true, 10),
('Kingston Fury Beast 32GB (2x16GB) DDR5 6000MHz CL36 RAM', '32GB (2x16GB) DDR5 RAM running at 6000MHz with CL36 timings. Intel XMP 3.0 and AMD EXPO certified. Aluminum heat spreader with low-profile design. On-die ECC for enhanced stability. Perfect for high-performance gaming and productivity builds.', 119.99, 'https://images.unsplash.com/photo-1591485423007-765bde4139ef?auto=format&fit=crop&w=600&q=80', '{"brand":"Kingston","category":"Memory"}', true, 10),
('Samsung 990 EVO Plus 2TB PCIe 4.0/5.0 NVMe SSD', '"Samsung 990 EVO Plus 2TB NVMe SSD with PCIe 4.0 x4 and PCIe 5.0 compatibility. Sequential read up to 7,150 MB/s and write up to 6,900 MB/s. Samsung V-NAND technology with 1,200 TBW endurance. Includes Samsung Magician software for optimization. Perfect for gaming and content creation."', 159.99, 'https://images.unsplash.com/photo-1587614382346-4ec70e388b28?auto=format&fit=crop&w=600&q=80', '{"brand":"Samsung","category":"Storage"}', true, 10),
('Arctic Liquid Freezer III 360 AIO CPU Cooler', 'Arctic Liquid Freezer III 360 AIO CPU cooler with 360mm radiator and three P12 PWM fans. VRM fan for motherboard cooling and push-pull capable design. Pre-applied MX-6 thermal paste with multi-socket mounting. Excellent cooling performance for high-end processors.', 109.99, 'https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=600&q=80', '{"brand":"Arctic","category":"Cooling"}', true, 10),
('Steelcase Series 2 Ergonomic Office Chair with Mesh Back', 'Ergonomic office chair with 4D adjustable arms and LiveBack technology. Breathable mesh back with lumbar support. Adjustable seat depth and tilt tension. Hard floor and carpet casters included. 12-year warranty. Perfect for home office and professional use.', 599.99, 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?auto=format&fit=crop&w=600&q=80', '{"brand":"Steelcase","category":"Furniture"}', true, 10),
('AMD Ryzen 7 7800X3D 8-Core Gaming Processor with 3D V-Cache', 'AMD Ryzen 7 7800X3D 8-core 16-thread gaming processor with 3D V-Cache technology. 104MB total cache with 5.0 GHz max boost. 120W TDP with AM5 socket compatibility. Features Zen 4 architecture on 5nm process with PCIe 5.0 and DDR5 support. Perfect for ultimate gaming performance.', 449.99, 'https://images.unsplash.com/photo-1591799264318-7e6ef8ddb7ea?auto=format&fit=crop&w=600&q=80', '{"brand":"AMD","category":"Processors"}', true, 10);